/* THE HOLD, part 2 of 2. Note the play cue is S.s1, NOT S.s2, and that is the
   whole trick: both instances tween over the identical absolute window, so at
   every t in the dissolve they are showing the same Lottie frame. Change this
   to S.s2 and the phone snaps back to frame 0 mid-cut. */
var phone2 = loadLottie("#s2-phone", L_phone_on_counter_night);
phone2.renderer.svgElement.setAttribute("preserveAspectRatio", "xMidYMid slice");
playLottie(phone2, S.s1, 6.00);
plateKen("#s2-phone", S.s2, 7.885, 1.10, 1.24);

fade("#s6-band", S.s6 + 1.20, 0.6);
/* 44 slips, each on its own arithmetic offset (i*7 mod 44) so the fill is
   deterministic — no Math.random anywhere in a composition. Built in the DOM
   rather than written out: forty-four hand-typed rects is forty-four chances
   to fat-finger a coordinate. The grid sits at y 680-950, below the centred
   type and clear of the watermark box. */
(function () {
  var NS = "http://www.w3.org/2000/svg", g = document.getElementById("s6-slips");
  for (var i = 0; i < 44; i++) {
    var r = document.createElementNS(NS, "rect");
    r.setAttribute("x", 426 + (i % 11) * 104);
    r.setAttribute("y", 680 + Math.floor(i / 11) * 78);
    r.setAttribute("width", 27); r.setAttribute("height", 36);
    r.setAttribute("opacity", 0);
    g.appendChild(r);
    tl.fromTo(r, { opacity: 0, y: 14 },
      { opacity: 0.9, y: 0, duration: 0.42, ease: "power2.out" },
      S.s6 + 1.35 + (((i * 7) % 44) / 44) * 2.6);
  }
})();

/* The calendar shares the measure bar's +1.30 cue deliberately: the days
   burning down and the balance draining are the same sentence. 105 frames over
   3.05s is 1.15x — inside the range where the build still reads as a build —
   and it lands the ring at +4.35, 0.03s before the cross-dissolve begins, so
   the ringed 20th is the last thing the scene holds. */
var cal = loadLottie("#s7-cal", L_calendar_20th_circled);
playLottie(cal, S.s7 + 1.30, 3.05);

